import json


_HTML = r'''<!doctype html>
<html lang="th">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>ThaiLLM Academic Chat</title>
<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>
<style>
:root{--bg:#212121;--side:#171717;--panel:#2f2f2f;--panel2:#383838;--text:#ececec;--muted:#a6a6a6;--line:#343434;--accent:#10a37f;--danger:#ef4444}
*{box-sizing:border-box}html,body{height:100%;margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input,textarea{font:inherit}.shell{height:100%;display:grid;grid-template-columns:260px 1fr;overflow:hidden}.sidebar{background:var(--side);border-right:1px solid #202020;display:flex;flex-direction:column;min-width:0}.side-top{padding:12px}.brand{display:flex;align-items:center;gap:10px;padding:8px 8px 14px;font-weight:750}.brand-mark{width:28px;height:28px;border-radius:9px;background:linear-gradient(135deg,#10a37f,#5eead4);display:grid;place-items:center;color:#08130f;font-weight:900}.new-btn,.searchbox{width:100%;border:1px solid #3d3d3d;border-radius:9px;background:transparent;color:var(--text)}.new-btn{padding:10px 12px;text-align:left;cursor:pointer}.new-btn:hover{background:#242424}.searchbox{margin-top:9px;padding:9px 10px;outline:none}.history{flex:1;overflow:auto;padding:4px 8px 12px}.group-label{padding:12px 8px 6px;color:#8a8a8a;font-size:11px;font-weight:700}.chat-row{position:relative;display:flex;align-items:center;gap:6px;border-radius:8px;padding:8px 8px;color:#d6d6d6;cursor:pointer;font-size:13px}.chat-row:hover,.chat-row.active{background:#2b2b2b}.chat-title{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.row-menu{opacity:0;border:0;background:transparent;color:#aaa;padding:2px 5px;cursor:pointer;border-radius:5px}.chat-row:hover .row-menu{opacity:1}.side-bottom{padding:10px;border-top:1px solid #292929}.tools-btn,.user-btn{width:100%;border:0;background:transparent;color:#ddd;border-radius:8px;padding:9px;text-align:left;cursor:pointer}.tools-btn:hover,.user-btn:hover{background:#272727}.user-line{display:flex;align-items:center;gap:9px}.avatar{width:28px;height:28px;border-radius:50%;background:#444;display:grid;place-items:center;font-size:12px;font-weight:800}.main{min-width:0;display:flex;flex-direction:column;position:relative}.topbar{height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border-bottom:1px solid rgba(255,255,255,.04)}.top-title{font-size:14px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.model{font-size:11px;color:#9d9d9d}.mobile-menu{display:none;border:0;background:transparent;color:#eee;font-size:22px;cursor:pointer}.thread{flex:1;overflow:auto;scroll-behavior:smooth}.thread-inner{width:min(780px,calc(100% - 34px));margin:0 auto;padding:26px 0 140px}.welcome{min-height:58vh;display:grid;place-items:center;text-align:center}.welcome h1{font-size:28px;margin:0 0 10px}.welcome p{margin:0;color:#a6a6a6}.suggestions{margin-top:22px;display:grid;grid-template-columns:1fr 1fr;gap:10px}.suggest{border:1px solid #484848;background:#292929;border-radius:14px;padding:12px;text-align:left;color:#eee;cursor:pointer;font-size:13px}.suggest:hover{background:#303030}.msg{display:grid;grid-template-columns:32px 1fr;gap:12px;margin:24px 0}.msg.user{grid-template-columns:1fr}.msg.user .bubble{justify-self:end;background:#303030;border-radius:18px;padding:10px 14px;max-width:80%}.msg.assistant .avatar{background:#10a37f;color:#062b21}.bubble{line-height:1.68;font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere}.meta{margin-top:9px;display:flex;gap:6px;flex-wrap:wrap}.tag{border:1px solid #4b4b4b;border-radius:999px;padding:3px 7px;color:#aaa;font-size:10px}.evidence{margin-top:10px;display:grid;gap:7px}.ev{border:1px solid #3d3d3d;border-radius:10px;background:#292929;padding:9px 10px;font-size:11px;color:#bdbdbd}.thinking{display:flex;align-items:center;gap:8px;color:#aaa;font-size:13px}.dots span{display:inline-block;width:5px;height:5px;background:#aaa;border-radius:50%;margin:0 2px;animation:b 1.1s infinite}.dots span:nth-child(2){animation-delay:.15s}.dots span:nth-child(3){animation-delay:.3s}@keyframes b{0%,70%,100%{opacity:.25;transform:translateY(0)}35%{opacity:1;transform:translateY(-3px)}}
.composer-wrap{position:absolute;left:0;right:0;bottom:0;background:linear-gradient(transparent,var(--bg) 27%);padding:34px 16px 18px}.composer{width:min(780px,100%);margin:auto;background:#303030;border:1px solid #494949;border-radius:24px;padding:8px 10px;box-shadow:0 8px 30px rgba(0,0,0,.2)}.composer textarea{width:100%;resize:none;max-height:180px;min-height:34px;border:0;outline:0;background:transparent;color:#fff;padding:8px 9px;line-height:1.45}.compose-actions{display:flex;align-items:center;justify-content:space-between}.icon-btn{border:0;background:transparent;color:#bbb;width:34px;height:34px;border-radius:50%;cursor:pointer}.icon-btn:hover{background:#414141}.send{background:#fff;color:#111}.send:disabled{opacity:.35;cursor:default}.hint{text-align:center;color:#777;font-size:10px;margin-top:7px}.modal-backdrop{position:fixed;inset:0;z-index:100;background:rgba(0,0,0,.66);display:none;place-items:center;padding:18px}.modal-backdrop.show{display:grid}.modal{width:min(460px,100%);background:#242424;border:1px solid #444;border-radius:16px;padding:20px}.modal h2{margin:0 0 6px}.modal p{color:#aaa;font-size:12px}.field{width:100%;border:1px solid #4b4b4b;background:#303030;color:#fff;border-radius:10px;padding:11px;margin-top:9px;outline:none}.modal-actions{display:flex;gap:8px;margin-top:12px}.primary,.secondary,.danger{border:0;border-radius:10px;padding:10px 13px;cursor:pointer;font-weight:700}.primary{background:#10a37f;color:white}.secondary{background:#393939;color:#eee}.danger{background:#4b1f24;color:#fecaca}.auth-state{margin-top:9px;font-size:11px;color:#aaa}.tool-section{border-top:1px solid #3b3b3b;padding-top:14px;margin-top:14px}.tool-section:first-of-type{border-top:0;margin-top:0;padding-top:0}.progress{height:7px;border-radius:999px;background:#3a3a3a;overflow:hidden;margin:10px 0}.progress>div{height:100%;width:0;background:#10a37f}.batch-list{max-height:200px;overflow:auto;border:1px solid #444;border-radius:10px}.batch-item{padding:8px;border-bottom:1px solid #3d3d3d;font-size:11px}.batch-item:last-child{border-bottom:0}.notice{padding:10px;border:1px solid #4a4a4a;border-radius:10px;background:#2b2b2b;color:#c8c8c8;font-size:11px}.empty-history{padding:18px 8px;color:#777;font-size:12px}.context{position:fixed;z-index:120;background:#2b2b2b;border:1px solid #494949;border-radius:10px;padding:5px;display:none;min-width:130px}.context.show{display:block}.context button{display:block;width:100%;border:0;background:transparent;color:#eee;padding:8px;text-align:left;border-radius:6px;cursor:pointer}.context button:hover{background:#3a3a3a}.context .del{color:#fda4af}
@media(max-width:760px){.shell{grid-template-columns:1fr}.sidebar{position:fixed;z-index:80;inset:0 auto 0 0;width:280px;transform:translateX(-100%);transition:.2s}.sidebar.open{transform:translateX(0);box-shadow:12px 0 40px rgba(0,0,0,.35)}.mobile-menu{display:block}.suggestions{grid-template-columns:1fr}.thread-inner{width:min(100% - 24px,780px)}.composer-wrap{padding-left:10px;padding-right:10px}.topbar{padding-left:10px}.msg.user .bubble{max-width:90%}}
</style>
</head>
<body>
<div class="shell">
  <aside class="sidebar" id="sidebar">
    <div class="side-top">
      <div class="brand"><div class="brand-mark">T</div><div>ThaiLLM Academic Chat</div></div>
      <button class="new-btn" id="newChat">＋ แชทใหม่</button>
      <input class="searchbox" id="searchChats" placeholder="ค้นหาแชท">
    </div>
    <div class="history" id="history"></div>
    <div class="side-bottom">
      <button class="tools-btn" id="toolsBtn">⚙ เครื่องมือแข่งขัน</button>
      <button class="user-btn" id="userBtn"><div class="user-line"><div class="avatar" id="userAvatar">G</div><div><div id="userName">Guest</div><div style="font-size:10px;color:#888" id="userSub">เข้าสู่ระบบเพื่อเก็บประวัติข้ามอุปกรณ์</div></div></div></button>
    </div>
  </aside>

  <main class="main">
    <header class="topbar"><div style="display:flex;align-items:center;gap:9px;min-width:0"><button class="mobile-menu" id="mobileMenu">☰</button><div class="top-title" id="conversationTitle">แชทใหม่</div></div><div class="model">OpenThaiGPT-ThaiLLM-8B-Instruct-v7.2</div></header>
    <div class="thread" id="thread"><div class="thread-inner" id="threadInner"></div></div>
    <div class="composer-wrap">
      <div class="composer"><textarea id="composer" rows="1" placeholder="พิมพ์ข้อความถึง ThaiLLM..."></textarea><div class="compose-actions"><button class="icon-btn" id="attachBtn" title="Question file">＋</button><button class="icon-btn send" id="sendBtn" title="Send">↑</button></div></div>
      <div class="hint">ถามภาษาไหน ตอบภาษานั้น · คำตอบอ้างอิงชุดข้อมูลหลักสูตร IT KMITL</div>
    </div>
  </main>
</div>

<div class="modal-backdrop" id="authModal"><div class="modal"><h2>เข้าสู่ระบบ</h2><p>ล็อกอินเพื่อเก็บบทสนทนาและเปิดดูย้อนหลังได้จากอุปกรณ์อื่น</p><input class="field" id="email" type="email" placeholder="Email"><input class="field" id="password" type="password" placeholder="Password"><div class="modal-actions"><button class="primary" id="signInBtn">Sign in</button><button class="secondary" id="signUpBtn">Create account</button><button class="secondary" id="closeAuth">ปิด</button></div><div class="auth-state" id="authState"></div></div></div>

<div class="modal-backdrop" id="toolsModal"><div class="modal"><h2>เครื่องมือแข่งขัน</h2><p>Batch question files และ API key สำหรับ browser session นี้</p>
<div class="tool-section"><div class="notice">อัปโหลด .xlsx / .csv แล้วระบบจะรันทุกคำถามผ่าน pipeline เดียวกับหน้าแชท และดาวน์โหลด CSV แบบ question,answer</div><input id="questionFile" type="file" accept=".xlsx,.csv" style="margin-top:10px"><div class="auth-state" id="fileState">ยังไม่ได้เลือกไฟล์</div><div class="progress"><div id="batchProgress"></div></div><div class="batch-list" id="batchList"></div><div class="modal-actions"><button class="primary" id="runBatch" disabled>Run all</button><button class="secondary" id="downloadBatch" disabled>Download CSV</button></div></div>
<div class="tool-section"><input class="field" id="apiKey" type="password" placeholder="ThaiLLM API key (optional)"><div class="modal-actions"><button class="secondary" id="saveApiKey">ใช้ key นี้ใน session</button><button class="secondary" id="clearApiKey">ใช้ Render key</button></div><div class="auth-state" id="keyState"></div></div>
<div class="modal-actions"><button class="secondary" id="closeTools">ปิด</button></div></div></div>

<div class="context" id="contextMenu"><button id="renameChat">เปลี่ยนชื่อ</button><button class="del" id="deleteChat">ลบแชท</button></div>
<script>
window.CHAT_CONFIG=__CHAT_CONFIG__;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
let sb=null,currentUser=null,currentConversation=null,conversations=[],messages=[],imported=[],batchResults=[],contextConversation=null;
const localKey='thaillm_guest_conversations_v1';
function apiHeaders(extra={}){const h={'Content-Type':'application/json',...extra},k=sessionStorage.getItem('thaillm_api_key');if(k)h['X-ThaiLLM-API-Key']=k;return h}
function titleFromQuestion(q){return String(q).replace(/\s+/g,' ').trim().slice(0,52)||'แชทใหม่'}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function nowIso(){return new Date().toISOString()}
function localLoad(){try{return JSON.parse(localStorage.getItem(localKey)||'[]')}catch(_){return []}}
function localSave(){localStorage.setItem(localKey,JSON.stringify(conversations))}
function groupFor(ts){const d=new Date(ts),now=new Date(),start=new Date(now.getFullYear(),now.getMonth(),now.getDate()),diff=Math.floor((start-d)/86400000);if(d>=start)return'วันนี้';if(diff<=1)return'เมื่อวาน';if(diff<=7)return'7 วันที่ผ่านมา';return'เก่ากว่านั้น'}
function renderHistory(filter=''){const root=$('#history');root.innerHTML='';const list=conversations.filter(c=>(c.title||'').toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at));if(!list.length){root.innerHTML='<div class="empty-history">ยังไม่มีบทสนทนา</div>';return}let g='';for(const c of list){const ng=groupFor(c.updated_at||c.created_at);if(ng!==g){g=ng;root.insertAdjacentHTML('beforeend',`<div class="group-label">${esc(g)}</div>`)}const row=document.createElement('div');row.className='chat-row'+(currentConversation?.id===c.id?' active':'');row.dataset.id=c.id;row.innerHTML=`<div class="chat-title">${esc(c.title||'แชทใหม่')}</div><button class="row-menu">•••</button>`;row.onclick=e=>{if(e.target.classList.contains('row-menu')){e.stopPropagation();openContext(c,e.clientX,e.clientY)}else openConversation(c.id)};root.appendChild(row)}}
function renderWelcome(){messages=[];$('#threadInner').innerHTML=`<div class="welcome"><div><h1>มีอะไรให้ช่วยเรื่องหลักสูตร IT KMITL?</h1><p>ถามต่อเนื่อง เปรียบเทียบหลักสูตร หรืออัปโหลดชุดคำถามแข่งขันได้</p><div class="suggestions"><button class="suggest">AIT กับ DSBA ต่างกันอย่างไร?</button><button class="suggest">หลักสูตร IT ปี 2565 มีความเชี่ยวชาญด้านใดบ้าง?</button><button class="suggest">这四个专业的专业课程类学分从高到低如何排列?</button><button class="suggest">IT International ใช้ภาษาอะไรในการเรียน?</button></div></div></div>`;document.querySelectorAll('.suggest').forEach(b=>b.onclick=()=>{$('#composer').value=b.textContent;sendMessage()})}
function renderMessages(){const root=$('#threadInner');if(!messages.length){renderWelcome();return}root.innerHTML=messages.map(m=>messageHtml(m)).join('');scrollBottom()}
function messageHtml(m){if(m.role==='user')return`<div class="msg user"><div class="bubble">${esc(m.content)}</div></div>`;const md=m.metadata||{},ev=(md.evidenceList||[]).slice(0,3);return`<div class="msg assistant"><div class="avatar">T</div><div><div class="bubble">${esc(m.content)}</div>${(md.status||md.programDetected)?`<div class="meta">${md.status?`<span class="tag">${esc(md.status)}</span>`:''}${md.programDetected?`<span class="tag">${esc(md.programDetected)}</span>`:''}</div>`:''}${ev.length?`<div class="evidence">${ev.map(e=>`<div class="ev"><b>${esc(e.sourceDocTitle||e.sourceDoc||'Evidence')}</b>${e.pageNumber?` · p.${e.pageNumber}`:''}<div>${esc(e.quoteTh||e.quoteEn||'')}</div></div>`).join('')}</div>`:''}</div></div>`}
function scrollBottom(){requestAnimationFrame(()=>{$('#thread').scrollTop=$('#thread').scrollHeight})}
function addThinking(){const root=$('#threadInner');root.insertAdjacentHTML('beforeend','<div class="msg assistant" id="thinking"><div class="avatar">T</div><div class="thinking">กำลังค้นหลักฐานและประมวลผล <span class="dots"><span></span><span></span><span></span></span></div></div>');scrollBottom()}
function removeThinking(){$('#thinking')?.remove()}
async function initSupabase(){const cfg=window.CHAT_CONFIG||{};if(cfg.supabaseUrl&&cfg.supabaseAnonKey&&window.supabase){sb=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data}=await sb.auth.getSession();currentUser=data.session?.user||null;sb.auth.onAuthStateChange((_e,s)=>{currentUser=s?.user||null;refreshAuthUi();loadConversations()})}refreshAuthUi();await loadConversations()}
function refreshAuthUi(){if(currentUser){const name=currentUser.email||'User';$('#userName').textContent=name;$('#userSub').textContent='ประวัติซิงก์กับบัญชีนี้';$('#userAvatar').textContent=name.slice(0,1).toUpperCase()}else{$('#userName').textContent='Guest';$('#userSub').textContent=sb?'เข้าสู่ระบบเพื่อเก็บประวัติข้ามอุปกรณ์':'Supabase ยังไม่ได้ตั้งค่า';$('#userAvatar').textContent='G'}}
async function loadConversations(){if(currentUser&&sb){const {data,error}=await sb.from('conversations').select('*').order('updated_at',{ascending:false});if(error){console.error(error);conversations=[]}else conversations=data||[]}else conversations=localLoad();currentConversation=null;renderHistory($('#searchChats').value);renderWelcome();$('#conversationTitle').textContent='แชทใหม่'}
async function openConversation(id){const c=conversations.find(x=>x.id===id);if(!c)return;currentConversation=c;$('#conversationTitle').textContent=c.title||'แชทใหม่';if(currentUser&&sb){const {data,error}=await sb.from('messages').select('*').eq('conversation_id',id).order('created_at',{ascending:true});messages=error?[]:(data||[])}else messages=(c.messages||[]);renderHistory($('#searchChats').value);renderMessages();$('#sidebar').classList.remove('open')}
async function ensureConversation(firstQuestion){if(currentConversation)return currentConversation;const title=titleFromQuestion(firstQuestion);if(currentUser&&sb){const {data,error}=await sb.from('conversations').insert({user_id:currentUser.id,title}).select().single();if(error)throw error;currentConversation=data;conversations.unshift(data)}else{currentConversation={id:uid(),user_id:null,title,created_at:nowIso(),updated_at:nowIso(),messages:[]};conversations.unshift(currentConversation);localSave()}$('#conversationTitle').textContent=title;renderHistory($('#searchChats').value);return currentConversation}
async function persistMessage(role,content,metadata={}){const c=currentConversation;if(!c)return;if(currentUser&&sb){const {data,error}=await sb.from('messages').insert({conversation_id:c.id,user_id:currentUser.id,role,content,metadata}).select().single();if(error)throw error;messages.push(data);await sb.from('conversations').update({updated_at:nowIso()}).eq('id',c.id)}else{const m={id:uid(),conversation_id:c.id,role,content,metadata,created_at:nowIso()};c.messages=c.messages||[];c.messages.push(m);c.updated_at=nowIso();messages.push(m);localSave()}renderHistory($('#searchChats').value)}
async function sendMessage(){const ta=$('#composer'),q=ta.value.trim();if(!q)return;ta.value='';autoSize();$('#sendBtn').disabled=true;try{await ensureConversation(q);await persistMessage('user',q,{});renderMessages();addThinking();const r=await fetch('/api/ask',{method:'POST',headers:apiHeaders(),body:JSON.stringify({question:q})});const d=await r.json();removeThinking();const answer=d.answer||d.answerTh||d.error||'ไม่สามารถสร้างคำตอบได้';await persistMessage('assistant',answer,{status:d.status||'',language:d.language||'',programDetected:d.programDetected||'',confidence:d.confidence??0,evidenceList:d.evidenceList||[],modelDisplay:d.modelDisplay||''});renderMessages()}catch(e){removeThinking();messages.push({id:uid(),role:'assistant',content:'เกิดข้อผิดพลาด: '+(e.message||e),metadata:{status:'ERROR'}});renderMessages()}finally{$('#sendBtn').disabled=false;ta.focus()}}
async function newChat(){currentConversation=null;messages=[];$('#conversationTitle').textContent='แชทใหม่';renderHistory($('#searchChats').value);renderWelcome();$('#sidebar').classList.remove('open');$('#composer').focus()}
function openContext(c,x,y){contextConversation=c;const m=$('#contextMenu');m.style.left=Math.min(x,innerWidth-145)+'px';m.style.top=Math.min(y,innerHeight-100)+'px';m.classList.add('show')}
async function renameCurrent(){if(!contextConversation)return;const title=prompt('ชื่อแชทใหม่',contextConversation.title||'');if(!title)return;if(currentUser&&sb)await sb.from('conversations').update({title}).eq('id',contextConversation.id);else{contextConversation.title=title;localSave()}contextConversation.title=title;if(currentConversation?.id===contextConversation.id)$('#conversationTitle').textContent=title;renderHistory($('#searchChats').value);$('#contextMenu').classList.remove('show')}
async function deleteCurrent(){if(!contextConversation||!confirm('ลบแชทนี้?'))return;const id=contextConversation.id;if(currentUser&&sb)await sb.from('conversations').delete().eq('id',id);else{conversations=conversations.filter(c=>c.id!==id);localSave()}conversations=conversations.filter(c=>c.id!==id);if(currentConversation?.id===id)newChat();else renderHistory($('#searchChats').value);$('#contextMenu').classList.remove('show')}
function autoSize(){const t=$('#composer');t.style.height='auto';t.style.height=Math.min(t.scrollHeight,180)+'px'}
function showAuth(){if(!sb){alert('ยังไม่ได้ตั้งค่า SUPABASE_URL และ SUPABASE_ANON_KEY บน Render');return}$('#authModal').classList.add('show')}
async function signIn(){const email=$('#email').value.trim(),password=$('#password').value;$('#authState').textContent='กำลังเข้าสู่ระบบ...';const {error}=await sb.auth.signInWithPassword({email,password});$('#authState').textContent=error?error.message:'เข้าสู่ระบบสำเร็จ';if(!error)setTimeout(()=>$('#authModal').classList.remove('show'),350)}
async function signUp(){const email=$('#email').value.trim(),password=$('#password').value;$('#authState').textContent='กำลังสร้างบัญชี...';const {error}=await sb.auth.signUp({email,password});$('#authState').textContent=error?error.message:'สร้างบัญชีแล้ว โปรดตรวจอีเมลหากระบบเปิด email confirmation'}
async function userAction(){if(currentUser&&sb){if(confirm('ออกจากระบบ?'))await sb.auth.signOut()}else showAuth()}
async function importFile(file){const buf=await file.arrayBuffer(),bytes=new Uint8Array(buf);let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const r=await fetch('/api/import-questions',{method:'POST',headers:apiHeaders(),body:JSON.stringify({filename:file.name,contentBase64:btoa(binary)})});const d=await r.json();if(!r.ok)throw Error(d.error||'Import failed');imported=d.questions||[];batchResults=[];$('#fileState').textContent=`${file.name} · ${imported.length} questions`;$('#batchList').innerHTML=imported.slice(0,30).map((q,i)=>`<div class="batch-item" data-i="${i}">${i+1}. ${esc(q)}</div>`).join('');$('#runBatch').disabled=!imported.length;$('#downloadBatch').disabled=true;$('#batchProgress').style.width='0%'}
async function runBatch(){if(!imported.length)return;batchResults=[];$('#runBatch').disabled=true;for(let i=0;i<imported.length;i++){const q=imported[i];try{const r=await fetch('/api/ask',{method:'POST',headers:apiHeaders(),body:JSON.stringify({question:q})});const d=await r.json();batchResults.push({question:q,answer:d.answer||d.answerTh||d.error||''})}catch(e){batchResults.push({question:q,answer:'ระบบไม่สามารถประมวลผลข้อนี้ได้: '+e.message})}$('#batchProgress').style.width=Math.round((i+1)/imported.length*100)+'%';$('#fileState').textContent=`Processing ${i+1}/${imported.length}`}$('#fileState').textContent=`เสร็จ ${batchResults.length}/${imported.length}`;$('#downloadBatch').disabled=false;$('#runBatch').disabled=false}
function csvCell(s){s=String(s??'');return /[",\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function downloadBatch(){const csv='\ufeffquestion,answer\r\n'+batchResults.map(x=>csvCell(x.question)+','+csvCell(x.answer)).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='question_answer.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#newChat').onclick=newChat;$('#sendBtn').onclick=sendMessage;$('#composer').oninput=autoSize;$('#composer').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}};$('#searchChats').oninput=e=>renderHistory(e.target.value);$('#userBtn').onclick=userAction;$('#mobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');$('#toolsBtn').onclick=()=>$('#toolsModal').classList.add('show');$('#attachBtn').onclick=()=>$('#toolsModal').classList.add('show');$('#closeTools').onclick=()=>$('#toolsModal').classList.remove('show');$('#closeAuth').onclick=()=>$('#authModal').classList.remove('show');$('#signInBtn').onclick=signIn;$('#signUpBtn').onclick=signUp;$('#renameChat').onclick=renameCurrent;$('#deleteChat').onclick=deleteCurrent;document.addEventListener('click',e=>{if(!e.target.closest('#contextMenu')&&!e.target.classList.contains('row-menu'))$('#contextMenu').classList.remove('show')});$('#questionFile').onchange=e=>{const f=e.target.files?.[0];if(f)importFile(f).catch(err=>$('#fileState').textContent=err.message)};$('#runBatch').onclick=runBatch;$('#downloadBatch').onclick=downloadBatch;$('#saveApiKey').onclick=()=>{const k=$('#apiKey').value.trim();if(k){sessionStorage.setItem('thaillm_api_key',k);$('#apiKey').value='';$('#keyState').textContent='ใช้ custom key สำหรับ session นี้แล้ว'}};$('#clearApiKey').onclick=()=>{sessionStorage.removeItem('thaillm_api_key');$('#keyState').textContent='กลับไปใช้ Render key แล้ว'};
initSupabase();
</script>
</body></html>'''


def render_chat_ui(config: dict) -> str:
    safe_config = json.dumps(config, ensure_ascii=False).replace("</", "<\\/")
    return _HTML.replace("__CHAT_CONFIG__", safe_config)
